        .cyber-neon-lines {
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            overflow: hidden;
            z-index: -1;
        }

        .neon-line {
            position: absolute;
            background: linear-gradient(90deg,
                rgba(255, 0,255, 0) 0%,
                rgba(255, 0,255, 0.8) 50%,
                rgba(255, 0, 255, 0) 100%);
            height: 1px;
            width: 100%;
            opacity: 0.5;
            animation: neon-line-move 8s linear infinite;
        }

        .neon-line:nth-child(1) {
            top: 20%;
            background: linear-gradient(90deg,
                rgba(0, 255, 255, 0) 0%,
                rgba(0, 255, 255, 0.8) 50%,
                rgba(0, 255, 255, 0) 100%);
            animation-delay: 0s;
        }

        .neon-line:nth-child(2) {
            top: 40%;
            background: linear-gradient(90deg,
                rgba(255, 0, 128,0) 0%,
                rgba(255, 0, 128, 0.8) 50%,
                rgba(255, 0, 128,0) 100%);
            animation-delay: 2s;
        }

        .neon-line:nth-child(3) {
            top: 60%;background: linear-gradient(90deg,
                rgba(255, 255,0, 0) 0%,
                rgba(255, 255, 0, 0.8) 50%,
                rgba(255, 255,0, 0) 100%);
            animation-delay: 4s;
        }

        .neon-line:nth-child(4) {
            top: 80%;
            background: linear-gradient(90deg,
                rgba(0, 255, 0,0) 0%,
                rgba(0, 255, 0, 0.8) 50%,
                rgba(0, 255, 0,0) 100%);
            animation-delay: 6s;
        }

        @keyframes neon-line-move {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }

        /* 添加故障效果 */.glitch-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
