            left: 0;
            width: 100%;
            height: 2px;
            background-color: rgba(255, 0, 255, 0.5);
            animation: glitch-overlay 2s infinite;
        }

        @keyframes glitch-overlay {
            0% { top: -10%; }
            20% { top: 20%; }
            40% { top: 50%; }
            60% { top: 70%; }
            80% { top: 90%; }
            100% { top: 110%; }
        }
